import {curveIntersections} from './curve-engine.js';
// Point-before-axis target priority follows VectorCraft tools/guides.rs; native Siluetra adapter.
import {worldPath,bounds} from './core.js';
import {visible,locked} from './model.js';
import {nearestPathPoint} from './vector-edit.js';
import {closestTarget} from './vectorcraft-adapted.js';
export function collectSnapTargets(project,view,exclude=[],options={}){const xs=[],ys=[],points=[],paths=[],lines=[];if(options.snapCenter){xs.push(project.centerAxis,0,project.document.widthPx);ys.push(project.document.heightPx/2,0,project.document.heightPx);}if(options.snapGuides)for(const g of project.guides?.[view]||[])(g.direction==='vertical'?xs:ys).push(g.position);const objects=project.views[view];if(options.snapObjects===false)return {xs,ys,points,paths};for(const o of objects){if(exclude.includes(o.id)||exclude.includes(o.source)||o.instanceOf&&exclude.includes(o.instanceOf)||!visible(project,view,o)||locked(project,view,o)||o.semanticType==='region'||o.regionSources)continue;if(options.snapBounds){const b=bounds(o,objects);xs.push(b.x,b.x+b.w/2,b.x+b.w);ys.push(b.y,b.y+b.h/2,b.y+b.h);}if(o.nodes&&options.snapNodes){const w=worldPath(o);for(const sp of [w,...w.subpaths||[]])for(const n of sp.nodes)points.push({x:n.x,y:n.y,label:'Nodo'});paths.push(o);if(options.snapIntersections!==false)for(const sp of [w,...w.subpaths||[]])for(let i=0;i<sp.nodes.length-(sp.closed?0:1);i++){const a=sp.nodes[i],b=sp.nodes[(i+1)%sp.nodes.length];lines.push({a,b});}}}
 if(lines.length<=160)for(let i=0;i<lines.length;i++)for(let j=i+1;j<lines.length;j++)for(const hit of curveIntersections(lines[i],lines[j]))points.push({...hit.point,label:'Intersección'});return {xs,ys,points,paths};}
export function snapPoint(p,targets,tolerance,{path=true}={}){let nearest=null;for(const q of targets.points){const distance=Math.hypot(q.x-p.x,q.y-p.y);if(distance<=tolerance&&(!nearest||distance<nearest.distance))nearest={point:q,distance,label:q.label||'Nodo'};}if(nearest)return {...nearest.point,lines:[],label:nearest.label};if(path){for(const o of targets.paths){const b=bounds(o);if(p.x<b.x-tolerance||p.x>b.x+b.w+tolerance||p.y<b.y-tolerance||p.y>b.y+b.h+tolerance)continue;const hit=nearestPathPoint(o,p);if(hit?.distance<=tolerance&&(!nearest||hit.distance<nearest.distance))nearest={...hit,label:'Trazado'};}if(nearest)return {...nearest.point,lines:[],label:nearest.label};}const x=closestTarget(p.x,targets.xs,tolerance),y=closestTarget(p.y,targets.ys,tolerance);return {x:x?.target??p.x,y:y?.target??p.y,lines:[...(x?[{x:x.target}]:[]),...(y?[{y:y.target}]:[])],label:x||y?'Alinear':''};}
export function snapTranslation(dx,dy,b,targets,tolerance,shift=false){const horizontal=Math.abs(dx)>=Math.abs(dy);if(shift){if(horizontal)dy=0;else dx=0;}let X=null,Y=null;for(const x of [b.x+dx,b.x+b.w/2+dx,b.x+b.w+dx]){const hit=closestTarget(x,targets.xs,tolerance);if(hit&&(!X||Math.abs(hit.delta)<Math.abs(X.delta)))X=hit;}for(const y of [b.y+dy,b.y+b.h/2+dy,b.y+b.h+dy]){const hit=closestTarget(y,targets.ys,tolerance);if(hit&&(!Y||Math.abs(hit.delta)<Math.abs(Y.delta)))Y=hit;}if(shift){if(horizontal)Y=null;else X=null;}return {dx:dx+(X?.delta||0),dy:dy+(Y?.delta||0),lines:[...(X?[{x:X.target}]:[]),...(Y?[{y:Y.target}]:[])]};}
